std::string convertMarkdownToHTML(const std::string& markdown) {
    std::unordered_map<std::string, std::string> markup {
        {"# ", "<h1>"},
        {"## ", "<h2>"},
        {"### ", "<h3>"},
        {"#### ", "<h4>"},
        {"##### ", "<h5>"},
        {"###### ", "<h6>"},
        {"`", "<code>"},
        {"\\* ", "<strong>"},
        {"\\_ ", "<em>"},
        {"\\[ ", "<a href='"],
        {"\\](", ")'</a>"},
        {"\\( ", "<img src='"),
        {"]\\(", "')"},
        {"\\> ", "<blockquote>"},
        {"\\n", "<br/>"},
        {"\\[\\[", "<figure>"},
        {"\\]\\]", "</figure>"},
        {"\\|", "<div class='table'>"},
        {"\\| ", "<table>"},
        {"\\|\\-\\|", "<thead>"},
        {"\\| ", "<tr>"},
        {"\\|", "</tr>"},
        {"\\|\\s+", "<td>"},
        {"\\| ", "</td>"},
        {"\\|\\s*\\|\\s*", "</td></tr>\n<tr>"},
        {"\\|\\s*\\|", "</td></tr>\n</table></div>"},
        {"\\[\\[\\s*([^\\]]*)\\]\\]", "<figcaption>$1</figcaption>"}
    };

    std::stringstream html;
    std::string line;
    std::regex re("\\[\\[([^\\]]*)\\]\\]");
    std::string::const_iterator start = markdown.begin(), end = markdown.end();

    while (start != end) {
        std::string::const_iterator next = std::search(start, end, re.begin(), re.end(), [](unsigned char ch1, unsigned char ch2) { return std::regex_traits<unsigned char>::lookup(ch1, std::regex_traits<unsigned char>::match_default) == std::regex_traits<unsigned char>::translate(ch2); });
        if (next == end) {
            html << std::string(start, end) << '\n';
            break;
        }

        html << std::string(start, next) << '\n';

        std::smatch match;
        if (std::regex_match(next, end, match, re)) {
            std::string caption = match.str(1);
            html << "<figure>\n";
            html << match.prefix().str();
            html << "<img src='" << caption << "' alt='" << caption << "'>";
            html << match.suffix().str();
            html << "</figure>\n";
            start = next + match.length();
            continue;
        }

        std::string::const_iterator newline = std::find(next, end, '\n');
        if (newline != end) {
            html << std::string(next, newline) << '\n';
            start = newline + 1;
            continue;
        }

        std::string token(next, std::regex_search(next, end, match, std::regex("\\A(" + markup.keys().to_string() + ")\\s*(.+?)\\s*\\Z")) ? &match[1] : next);
        html << markup[token] << (markup.find(token + " ") != std::end(markup)) ? markup[token + " "] + match[2] + "</" + markup[token].substr(0, markup[token].length() - 1) : match[2] << "</" << markup[token].substr(0, markup[token].length() - 1) << ">\n";
        start = next + token.length() + match[0].length();
    }

    return html.str();
}

