Here's a sample C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    // Set up variables
    string filename, word;
    int count = 0;
    unordered_map<string, int> word_count;

    // Prompt user for input
    cout << "Enter the name of the text file: ";
    getline(cin, filename);

    // Prompt user for word to search for
    cout << "Enter the word to search for: ";
    getline(cin, word);

    // Open the file
    ifstream file(filename);

    // Check if file was successfully opened
    if (!file.is_open()) {
        cerr << "Error: could not open file " << filename << endl;
        return 1;
    }

    // Read file line by line
    string line;
    while (getline(file, line)) {
        // Split the line into words
        istringstream iss(line);
        string word_in_line;
        while (iss >> word_in_line) {
            // Check if the word matches the search word
            if (word_in_line == word) {
                // Increment the count if the word matches
                count++;
                // Increment the word count in the map
                word_count[word]++;
            }
        }
    }

    // Close the file
    file.close();

    // Display the results
    cout << "Total occurrences of \"" << word << "\": " << count << endl;
    cout << "Occurrences of \"" << word << "\" in the file: " << word_count[word] << endl;

    return 0;
}
```

The program uses the `unordered_map` container to store the count of each unique word found in the file. This allows for efficient counting of multiple occurrences of the same word. The program prompts the user for the filename and search word, opens the file, reads it line by line, and increments the count and map for each occurrence of the search word. Finally, the program displays the total number of occurrences in the file and the count for the search word specifically.
